import numpy as np
# invalid input: a Poisson ratio of 0.5 lies outside (-1, 0.5) and must raise ValueError
E = 200.0
nu = 0.5
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: elastic_operator(E, nu)), target)

